<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api } from '../api'
import { backendMessage, formatDateTime, statusText, zh } from '../localize'
const route = useRoute(), router = useRouter(), courses = ref([]), current = ref(null), documents = ref([]), loading = ref(true), saving = ref(false), uploading = ref(false), error = ref(''), dialog = ref(false), draft = ref({ name: '', description: '' }), fileInput = ref(null)
const selectedId = computed(() => route.params.id)
async function loadCourses() { loading.value = true; error.value = ''; try { courses.value = await api.courses(); if (selectedId.value) await select(selectedId.value, false) } catch (e) { error.value = e.message } finally { loading.value = false } }
async function select(id, navigate = true) { try { current.value = await api.course(id); documents.value = await api.documents(id); if (navigate) router.push(`/courses/${id}`) } catch (e) { error.value = e.message } }
async function createCourse() { saving.value = true; try { const course = await api.createCourse(draft.value); dialog.value = false; draft.value = { name: '', description: '' }; await loadCourses(); await select(course.id) } catch (e) { error.value = e.message } finally { saving.value = false } }
async function upload(event) { const file = event.target.files?.[0]; if (!file || !current.value) return; uploading.value = true; try { const document = await api.upload(current.value.id, file); documents.value = [document, ...documents.value]; if (document.status === 'FAILED') error.value = backendMessage(document.errorMessage) || '文档处理失败。' } catch (e) { error.value = backendMessage(e.message) } finally { uploading.value = false; event.target.value = '' } }
async function removeDocument(document) { try { await api.deleteDocument(current.value.id, document.id); documents.value = documents.value.filter(item => item.id !== document.id) } catch (e) { error.value = e.message } }
onMounted(loadCourses); watch(selectedId, id => { if (id && id !== current.value?.id) select(id, false); if (!id) current.value = null })
</script>
<template><el-alert v-if="error" class="page-alert" type="error" :title="error" show-icon @close="error = ''"/><section v-if="!selectedId" class="courses-layout"><div class="section-heading"><div><span class="eyebrow">课程库</span><h2>课程与学习资料</h2><p>创建课程，上传 PDF，并建立课程知识库。</p></div><el-button type="primary" @click="dialog = true">创建课程</el-button></div><el-skeleton v-if="loading" :rows="5" animated/><div v-else-if="!courses.length" class="empty-card"><el-empty description="还没有课程，创建第一门课程开始吧。"><el-button type="primary" @click="dialog = true">创建课程</el-button></el-empty></div><div v-else class="course-grid"><button v-for="course in courses" :key="course.id" class="course-card" @click="select(course.id)"><span class="course-icon">⌁</span><h3>{{zh(course.name)}}</h3><p>{{zh(course.description)||'尚未添加课程描述'}}</p><div class="course-meta"><small>{{course.documentCount}} 份资料</small><small>{{course.readyDocumentCount}} 份就绪</small></div></button></div></section><section v-else-if="current" class="detail-layout"><button class="back-link" @click="router.push('/courses')">← 返回课程</button><div class="course-detail-header"><div><span class="eyebrow">课程知识库</span><h2>{{zh(current.name)}}</h2><p>{{zh(current.description)||'尚未添加课程描述'}}</p></div><div class="task-actions"><router-link :to="{path:'/memory',query:{courseId:current.id}}"><el-button>生成记忆卡片</el-button></router-link><input ref="fileInput" class="file-input" type="file" accept="application/pdf" @change="upload"><el-button type="primary" :loading="uploading" @click="fileInput.click()">{{uploading?'处理中…':'上传 PDF'}}</el-button></div></div><div class="document-panel"><div class="panel-title"><h3>课程资料</h3><span>{{documents.length}} 个文件</span></div><el-empty v-if="!documents.length" description="尚未上传资料。上传文本型 PDF 后即可建立课程知识库。"/><div v-else class="document-list"><article v-for="document in documents" :key="document.id" class="document-row"><div class="doc-file">PDF</div><div class="doc-main"><strong>{{document.originalFilename}}</strong><small>{{formatDateTime(document.uploadedAt)}} <template v-if="document.errorMessage">· {{backendMessage(document.errorMessage)}}</template></small><small v-if="document.status==='PROCESSING'">正在提取文本并创建向量…</small><small v-if="document.status==='FAILED'" class="retry-hint">配置已完成，请删除该失败记录并重新上传原 PDF。</small></div><el-tag :type="document.status==='READY'?'success':document.status==='FAILED'?'danger':'warning'">{{statusText[document.status]||document.status}}</el-tag><el-button text type="danger" @click="removeDocument(document)">删除</el-button></article></div></div></section><el-dialog v-model="dialog" title="创建课程" width="440px"><el-form label-position="top"><el-form-item label="课程名称" required><el-input v-model="draft.name" placeholder="例如：操作系统"/></el-form-item><el-form-item label="课程描述"><el-input v-model="draft.description" type="textarea" :rows="3" placeholder="这门课程主要学习什么？"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="createCourse">创建课程</el-button></template></el-dialog></template>
